import './paginas/Demandas/Demandas.css'
import { useState, useEffect } from "react";
import axios from 'axios';

function MainDemanda() {
    const [paciente, setPaciente] = useState("");
    const [atividade, setAtividade] = useState("");
    const [terapeuta, setTerapeuta] = useState("");
    const [demandas, setDemandas] = useState([]);
    
    // Estados para armazenar as listas de opções
    const [pacientes, setPacientes] = useState([]);
    const [atividades, setAtividades] = useState([]);
    const [terapeutas, setTerapeutas] = useState([]);

    useEffect(() => {
        getDemandas();
    }, []); // Array vazio para executar apenas uma vez ao montar

    const getDemandas = async () => {
        try {
            const response = await axios.get('http://localhost:3001/listarDemanda');

            if (response) {
                setDemandas(response.data);
                
                // Extrair dados únicos para os selects (ajuste conforme sua estrutura de dados)
                const listaPacientes = response.data.map(d => d.paciente).filter((v, i, a) => a.indexOf(v) === i);
                const listaAtividades = response.data.map(d => d.atividade).filter((v, i, a) => a.indexOf(v) === i);
                const listaTerapeutas = response.data.map(d => d.terapeuta).filter((v, i, a) => a.indexOf(v) === i);
                
                setPacientes(listaPacientes);
                setAtividades(listaAtividades);
                setTerapeutas(listaTerapeutas);
            }
            else {
                console.log("erro ao carregar as demandas")
            }
        }
        catch (error) {
            console.error("Erro ao buscar demandas:", error);
        }
    }

    const handleSubmit = (e) => {
        e.preventDefault();
        
        // Aqui você pode fazer o POST para cadastrar a demanda
        const novaDemanda = {
            paciente,
            atividade,
            terapeuta
        };
        
        console.log("Cadastrando demanda:", novaDemanda);
        // axios.post('http://localhost:3001/cadastrarDemanda', novaDemanda);
    };

    return (
        <main className="col-md-12 ms-sm-auto col-lg-12 px-md-4 container-fluid d-flex flex-column align-items-center">
            <div className="container mt-3">
                <h2 className="titulo-principal">
                    Cadastro de demanda
                </h2>
                <div className="caixa-cadastro mx-auto">
                    <form onSubmit={handleSubmit}>
                        <div className="mb-3">
                            <label className="form-label texto-label">Paciente:</label>
                            <select
                                className="form-select campo-input"
                                value={paciente}
                                onChange={(e) => setPaciente(e.target.value)}
                            >
                                <option value="">Selecione o paciente</option>
                                {pacientes.map((pac, index) => (
                                    <option key={index} value={pac}>
                                        {pac}
                                    </option>
                                ))}
                            </select>
                        </div>

                        <div className="mb-3">
                            <label className="form-label texto-label">Atividade:</label>
                            <select
                                className="form-select campo-input"
                                value={atividade}
                                onChange={(e) => setAtividade(e.target.value)}
                            >
                                <option value="">Selecione a atividade</option>
                                {atividades.map((ativ, index) => (
                                    <option key={index} value={ativ}>
                                        {ativ}
                                    </option>
                                ))}
                            </select>
                        </div>

                        <div className="mb-3">
                            <label className="form-label texto-label">Terapeuta:</label>
                            <select
                                className="form-select campo-input"
                                value={terapeuta}
                                onChange={(e) => setTerapeuta(e.target.value)} 
                            >
                                <option value="">Selecione o terapeuta</option>
                                {terapeutas.map((ter, index) => (
                                    <option key={index} value={ter}>
                                        {ter}
                                    </option>
                                ))}
                            </select>
                        </div>

                        <div className="text-center">
                            <button type="submit" className="botao-cadastrar">
                                Cadastrar
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        </main>
    );
}

export default MainDemanda;
